namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please enter at least one ingredient.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please enter at least one step.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Baguette", "Tomatoes", "Basil", "Garlic", "Olive oil"],
            Steps = ["Slice and toast bread.", "Dice tomatoes with basil and garlic.", "Top bread with mixture and drizzle with oil."],
            AverageRating = 4.2, RatingCount = 15
        },
        new()
        {
            Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers",
            Ingredients = ["Button mushrooms", "Cream cheese", "Garlic", "Parsley", "Breadcrumbs"],
            Steps = ["Remove stems from mushrooms.", "Mix filling ingredients.", "Stuff caps and bake at 375°F for 20 min."],
            AverageRating = 4.5, RatingCount = 8
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan", "Black pepper"],
            Steps = ["Cook pasta al dente.", "Fry pancetta until crisp.", "Toss hot pasta with egg and cheese mixture off heat.", "Season with pepper and serve."],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 4, Title = "Chicken Stir-Fry", Category = "Main Courses", CategorySlug = "main-courses",
            Ingredients = ["Chicken breast", "Bell peppers", "Soy sauce", "Ginger", "Rice"],
            Steps = ["Slice chicken and vegetables.", "Stir-fry chicken until cooked.", "Add vegetables and sauce.", "Serve over rice."],
            AverageRating = 4.0, RatingCount = 23
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour"],
            Steps = ["Melt chocolate and butter.", "Whisk eggs with sugar.", "Fold in flour and chocolate mixture.", "Bake at 425°F for 12 min."],
            AverageRating = 4.9, RatingCount = 31
        },
        new()
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts",
            Ingredients = ["Ladyfingers", "Mascarpone", "Espresso", "Cocoa powder", "Eggs", "Sugar"],
            Steps = ["Dip ladyfingers in espresso.", "Layer with mascarpone cream.", "Refrigerate overnight.", "Dust with cocoa before serving."],
            AverageRating = 4.7, RatingCount = 19
        }
    ];

    public List<Recipe> GetByCategory(string categorySlug)
        => _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public List<(string Name, string Slug)> GetCategories()
        => _recipes.Select(r => (r.Category, r.CategorySlug)).Distinct().ToList();

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var nextId = _recipes.Max(r => r.Id) + 1;
        var categorySlug = submission.Category.ToLower().Replace(" ", "-");
        _recipes.Add(new Recipe
        {
            Id = nextId,
            Title = submission.Title,
            Category = submission.Category,
            CategorySlug = categorySlug,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

