else
{
    var recipes = RecipeService.GetByCategory(CategorySlug);
    <h1>@recipes.FirstOrDefault()?.Category</h1>
    <a href="recipes" class="btn btn-sm btn-outline-secondary mb-3">← All Categories</a>

    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="text-muted">
                                ⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

