@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

@if (Recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@Recipe.Title - RecipeShare</PageTitle>

    <a href="recipes/@Recipe.CategorySlug" class="btn btn-sm btn-outline-secondary mb-3">← Back to @Recipe.Category</a>

    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <hr />
    <h4>Rate this Recipe</h4>
    <StarRating RecipeId="Recipe.Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating" role="group" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button type="button"
                class="btn btn-link p-0 fs-3 @(star <= (HoverRating ?? SelectedRating) ? "text-warning" : "text-secondary")"
                @onclick="() => SubmitRating(star)"
                @onmouseover="() => HoverRating = star"
                @onmouseout="() => HoverRating = null"
                aria-label="@star stars">
            ★
        </button>
    }
</div>

@if (Submitted)
{
    <p class="text-success mt-2">Thanks for rating! You gave @SelectedRating star(s).</p>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int? HoverRating { get; set; }
    private bool Submitted { get; set; }

    private void SubmitRating(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmissionSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the collection.
    </div>
    <button class="btn btn-primary" @onclick="ResetForm">Submit Another</button>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Submission.Title" />
            <ValidationMessage For="() => Submission.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Appetizers">Appetizers</option>
                <option value="Main Courses">Main Courses</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => Submission.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Submission.Ingredients" />
            <ValidationMessage For="() => Submission.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="Submission.Steps" />
            <ValidationMessage For="() => Submission.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool SubmissionSuccess { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(Submission);
        SubmissionSuccess = true;
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmissionSuccess = false;
    }
}

